/* ============================================================
   إعداد عنوان الخادم الخلفي (Backend Base URL)
   -----------------------------------------------------------
   عند التشغيل محليًا على جهازك، يستخدم الموقع تلقائيًا
   http://localhost:5000 (لا حاجة لأي تعديل).
   عند رفع الموقع فعليًا على الإنترنت (سيرفر مجاني)، عدّل السطر
   أدناه (PRODUCTION_BACKEND_URL) وضع فيه رابط خادم الـ API
   الحقيقي الذي رفعته (مثال: خادم مجاني على Render)، بالصيغة:
   "https://your-app-name.onrender.com" (بدون شرطة مائلة / في النهاية).
   التبديل بين محلي/فعلي يتم تلقائيًا حسب اسم النطاق الذي يُفتح
   منه الموقع، فلا حاجة لأي تعديل آخر في الكود بعد ذلك.
============================================================ */
const PRODUCTION_BACKEND_URL = "https://fatwa-api-p9op.onrender.com";
const BACKEND_BASE_URL = (
    location.hostname === "localhost" || location.hostname === "127.0.0.1" || location.protocol === "file:"
) ? "http://localhost:5000" : PRODUCTION_BACKEND_URL;
/* نقطة نهاية خدمة حساب المستخدم (تسجيل/دخول/مزامنة)، تعتمد على نفس الخادم
   الخلفي المستخدم أصلًا لـ "مرشد" والفتاوى (fatwa_api_server.py)، لذا لا حاجة
   لتعديل سياسة CSP أعلاه — راجع ملف account_api_server.py المرفق لدمج المسارات. */
const ACCOUNT_API_ENDPOINT = BACKEND_BASE_URL + "/api/account";

/* ============================================================
   أدوات الأمان الأساسية: تعقيم المدخلات (Input Sanitization)
   والتحقق من صحة النماذج (Form Validation) لحماية الموقع من
   ثغرات XSS الشائعة الناتجة عن إدراج نص المستخدم مباشرة داخل
   innerHTML، ومن قيم رقمية غير منطقية في حاسبة الزكاة.
============================================================ */

// يحوّل أي نص خام (قد يكون من المستخدم أو من واجهة خارجية) إلى
// نص آمن للإدراج داخل innerHTML، بمنع تنفيذ أي وسوم HTML/JS.
function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str).replace(/[&<>"']/g, (ch) => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[ch]));
}

// تحقق عام لحقول البحث/النصوص: يحذف وسوم HTML ويحدّ الطول لمنع
// إرسال حمولات ضخمة أو كود مضمّن عبر النماذج.
function sanitizeTextInput(value, maxLength = 300) {
    if (typeof value !== 'string') return '';
    return value.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

// تحقق من الحقول الرقمية (مثل حاسبة الزكاة): يمنع القيم السالبة
// أو غير الرقمية أو القيم الشاذة الكبيرة جدًا، ويعيد رقمًا صالحًا فقط.
function sanitizeNumberInput(value, { min = 0, max = 1e12 } = {}) {
    const num = parseFloat(value);
    if (isNaN(num) || !isFinite(num)) return 0;
    return Math.min(Math.max(num, min), max);
}

