let currentQuoteIndex = 0;

async function loadAllQuranQuotes() {
    try {
        const [quranRes, tafseerRes] = await Promise.all([
            fetch('https://api.alquran.cloud/v1/quran/quran-uthmani'),
            fetch('https://api.alquran.cloud/v1/quran/ar.muyassar')
        ]);
        const quranData = await quranRes.json();
        const tafseerData = await tafseerRes.json();

        if (quranData.code === 200 && tafseerData.code === 200) {
            const loadedQuotes = [];
            quranData.data.surahs.forEach((surah, sIdx) => {
                const tafseerSurah = tafseerData.data.surahs[sIdx];
                surah.ayahs.forEach((ayah, aIdx) => {
                    const tafseerAyah = tafseerSurah.ayahs[aIdx];
                    loadedQuotes.push({
                        text: `"${ayah.text}" [سورة ${surah.name} - آية ${ayah.numberInSurah}]`,
                        tafseer: `التفسير المختصر: ${tafseerAyah.text}`
                    });
                });
            });
            if (loadedQuotes.length > 500) {
                quotesList.length = 0;
                quotesList.push(...loadedQuotes);
            }
        }
    } catch (e) {
        console.log("استخدام القائمة الأولية للآيات");
    }
}
// تسريع بدء التشغيل: بطاقة "آية وخاطرة اليوم" تعمل فورًا بالقائمة الأساسية
// الجاهزة أعلاه، فنؤجل تحميل القرآن الكريم كاملاً مع تفسيره (طلبان شبكيان
// كبيران) بضع ثوانٍ بعد ظهور الصفحة، بدل تحميلهما فور فتح الموقع مباشرة.
// الميزة نفسها لا تزال تعمل بكامل نطاقها، فقط يتأخر تحميلها الموسّع قليلًا.
setTimeout(() => loadAllQuranQuotes(), 2000);

document.getElementById('next-quote-btn').addEventListener('click', () => {
    currentQuoteIndex = (currentQuoteIndex + 1) % quotesList.length;
    const q = quotesList[currentQuoteIndex];
    document.getElementById('daily-quote-text').textContent = q.text;
    document.getElementById('daily-quote-tafseer').innerHTML = `<strong>التفسير المختصر:</strong> ${q.tafseer.replace('التفسير المختصر: ', '')}`;
});

document.getElementById('copy-quote-btn').addEventListener('click', () => {
    const txt = document.getElementById('daily-quote-text').textContent + "\n" + document.getElementById('daily-quote-tafseer').textContent;
    navigator.clipboard.writeText(txt).then(() => showToast("تم نسخ الآية والتفسير بنجاح"));
});

document.getElementById('share-quote-btn').addEventListener('click', () => {
    const txt = document.getElementById('daily-quote-text').textContent;
    openShareAyahModal(txt);
});

