async function fetchHadithFromApi(num = null) {
    const book = document.getElementById('hadith-book-select').value;
    const numInput = document.getElementById('hadith-number-input');
    const textDisplay = document.getElementById('hadith-display-text');
    const titleDisplay = document.getElementById('hadith-title');

    // الأربعون النووية محفوظة بالكامل (٤٢ حديثًا) داخل التطبيق نفسه،
    // فهي تُعرض مباشرة من غير أي اتصال بالإنترنت وتعمل دومًا حتى بلا شبكة
    // (مجموعة كاملة ومغلقة أصلاً، فلا فرق بين وضعي الاتصال وعدمه هنا)
    if (book === 'ara-nawawi') {
        numInput.max = nawawiHadiths.length;
        let hadithNum = parseInt(num || numInput.value || 1);
        if (isNaN(hadithNum)) hadithNum = 1;
        hadithNum = Math.min(Math.max(hadithNum, 1), nawawiHadiths.length);
        const item = nawawiHadiths[hadithNum - 1];
        textDisplay.innerHTML = `"${item.text}"<div style="margin-top:16px;font-size:0.75em;color:var(--text-muted);font-weight:700;font-family:inherit;">الراوي: ${item.narrator} — ${item.source}</div>`;
        titleDisplay.textContent = `الأربعون النووية - الحديث رقم (${hadithNum}): ${item.title}`;
        currentHadithNum = hadithNum;
        numInput.value = hadithNum;
        recordLastHadith(book, hadithNum, titleDisplay.textContent);
        return;
    }

    numInput.removeAttribute('max');

    const hadithNum = num || numInput.value || 1;

    // عرض حديث محلي احتياطي (يعمل دون إنترنت دائمًا) عند تعذّر
    // الوصول للـ API أو عدم توفر نسخة مخزّنة له مسبقًا
    // كل كتاب له مجموعته المحفوظة محليًا الخاصة به (البخاري، مسلم، أبو داود، الترمذي، النسائي، ابن ماجه)
    const localPools = {
        'ara-bukhari': bukhariHadiths,
        'ara-muslim': muslimHadiths,
        'ara-abudawud': abudawudHadiths,
        'ara-tirmidhi': tirmidhiHadiths,
        'ara-nasai': nasaiHadiths,
        'ara-ibnmajah': ibnmajahHadiths
    };
    const offlineBookNames = {
        'ara-bukhari': 'صحيح البخاري',
        'ara-muslim': 'صحيح مسلم',
        'ara-abudawud': 'سنن أبي داود',
        'ara-tirmidhi': 'سنن الترمذي',
        'ara-nasai': 'سنن النسائي',
        'ara-ibnmajah': 'سنن ابن ماجه'
    };
    const showOfflineFallback = () => {
        const localPool = localPools[book] || hadithsList;
        const item = localPool[Math.floor(Math.random() * localPool.length)];
        textDisplay.innerHTML = `"${item.text}"<div style="margin-top:16px;font-size:0.75em;color:var(--text-muted);font-weight:700;font-family:inherit;">الراوي: ${item.narrator} — ${item.source}</div>`;
        titleDisplay.textContent = `${offlineBookNames[book] || item.source} - حديث شريف (وضع بلا إنترنت)`;
    };

    // إذا كان الجهاز غير متصل بالإنترنت أصلاً، اعرض الحديث المحفوظ محليًا
    // فورًا دون أي محاولة اتصال أو رسالة انتظار
    if (!navigator.onLine) { showOfflineFallback(); return; }

    textDisplay.textContent = "جاري جلب الحديث الشريف من الكتب الشاملة...";

    try {
        // مهلة قصيرة (٤ ثوانٍ) للاتصال؛ فبعض الأجهزة تُبقي navigator.onLine
        // صحيحة رغم انقطاع الشبكة الفعلي (كالاتصال بشبكة بلا إنترنت فعلي)
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 4000);
        const res = await fetch(`https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/${book}/${hadithNum}.json`, { signal: controller.signal });
        clearTimeout(timeoutId);
        if (!res.ok) { showOfflineFallback(); return; }
        const data = await res.json();
        if (data && data.hadiths && data.hadiths[0]) {
            textDisplay.textContent = `"${data.hadiths[0].text}"`;
            const bookNames = {
                'ara-bukhari': 'صحيح البخاري',
                'ara-muslim': 'صحيح مسلم',
                'ara-abudawud': 'سنن أبي داود',
                'ara-tirmidhi': 'سنن الترمذي',
                'ara-nasai': 'سنن النسائي',
                'ara-ibnmajah': 'سنن ابن ماجه',
                'ara-nawawi': 'الأربعون النووية'
            };
            titleDisplay.textContent = `${bookNames[book]} - حديث رقم (${hadithNum})`;
            currentHadithNum = parseInt(hadithNum);
            numInput.value = currentHadithNum;
            recordLastHadith(book, currentHadithNum, titleDisplay.textContent);
        } else {
            showOfflineFallback();
        }
    } catch (e) {
        showOfflineFallback();
    }
}

function fetchHadithByNumber() {
    const num = document.getElementById('hadith-number-input').value;
    fetchHadithFromApi(num);
}

function fetchNextApiHadith(step) {
    const nextNum = Math.max(1, currentHadithNum + step);
    fetchHadithFromApi(nextNum);
}

function fetchRandomApiHadith() {
    const book = document.getElementById('hadith-book-select').value;
    // الأربعون النووية فقط ثابتة ومحدودة العدد (٤٢ حديثًا) وتُعرض محليًا دومًا،
    // أما باقي الكتب فتُجلب عبر الإنترنت ضمن نطاق العدد التقريبي المعروف لأحاديث كل كتاب
    const approxTotals = {
        'ara-bukhari': 7563,
        'ara-muslim': 7500,
        'ara-abudawud': 5274,
        'ara-tirmidhi': 3956,
        'ara-nasai': 5758,
        'ara-ibnmajah': 4341
    };
    const maxNum = (book === 'ara-nawawi') ? nawawiHadiths.length : (approxTotals[book] || 300);
    const randomNum = Math.floor(Math.random() * maxNum) + 1;
    fetchHadithFromApi(randomNum);
}

// تُجمَّع هنا كل المؤقتات المؤجَّلة (setTimeout) الناتجة عن تبديل الصفحة، حتى
// يتم إلغاء أي مؤقت سابق لم يُنفَّذ بعد كلما ضغط المستخدم على قسم جديد بسرعة.
// هذا يمنع تراكم عشرات النداءات (إعادة حساب مؤشرات التمرير، تمرير الصفحة...)
// فوق بعضها عند التنقّل السريع بين الأقسام، وهو السبب الرئيسي للإحساس
// بالتقطّع/التهنيج أثناء الانتقال المتلاحق.
let __pageSwitchTimers = [];
function __clearPageSwitchTimers() {
    __pageSwitchTimers.forEach(id => clearTimeout(id));
    __pageSwitchTimers = [];
}

function switchPage(pageId, event) {
    if (event) event.preventDefault();

    // إلغاء أي عمل مؤجَّل من عملية تبديل صفحة سابقة لم يكتمل بعد
    __clearPageSwitchTimers();

    document.querySelectorAll('.page-view').forEach(p => p.classList.remove('active-page'));
    const targetPage = document.getElementById(`page-${pageId}`);
    if (targetPage) targetPage.classList.add('active-page');

    document.querySelectorAll('.nav-links a').forEach(l => l.classList.remove('active'));
    if (event && event.currentTarget) {
        event.currentTarget.classList.add('active');
    } else {
        const matching = document.querySelector(`.nav-links a[data-target="${pageId}"]`);
        if (matching) matching.classList.add('active');
    }

    if (pageId === 'fatwa') {
        __pageSwitchTimers.push(setTimeout(() => {
            document.getElementById('fatwa-categories')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 60));
    } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    // عند فتح قسم "المواعظ": نبدأ اتصالًا خفيفًا بخادم الصوتيات مبكرًا (قبل
    // ضغط المستخدم على تشغيل أي مقطع فعليًا) حتى لا يبطئ إنشاء الاتصال أول تشغيل،
    // ونبني قائمة البطاقات (218 عنصرًا) الآن فقط بدل بنائها فور تحميل الموقع
    if (pageId === 'sounds') {
        if (typeof warmupSoundsConnection === 'function') warmupSoundsConnection();
        if (typeof ensureSoundsLoaded === 'function') ensureSoundsLoaded();
    }

    // تحميل قائمة القرّاء والإذاعات فقط عند فتح صفحتيهما فعليًا (وليس فور
    // فتح الموقع) لتسريع بدء التشغيل دون حذف أي من الخدمتين
    if (pageId === 'quran' && typeof ensureRecitersLoaded === 'function') {
        ensureRecitersLoaded();
    }
    if (pageId === 'radio' && typeof ensureRadiosLoaded === 'function') {
        ensureRadiosLoaded();
    }
    if (pageId === 'azkar' && typeof ensureAzkarDefaultLoaded === 'function') {
        ensureAzkarDefaultLoaded();
    }
    if (pageId === 'fatwa' && typeof ensureFatwaGridLoaded === 'function') {
        ensureFatwaGridLoaded();
    }

    // إعادة حساب مؤشرات "يوجد المزيد" بعد ظهور القسم الجديد فعليًا في الصفحة
    __pageSwitchTimers.push(setTimeout(() => { if (typeof refreshAllScrollHints === 'function') refreshAllScrollHints(); }, 80));

    // إظهار/إخفاء شريط الصوت المصغّر حسب الصفحة الحالية: يظهر داخل قسم
    // "القرآن الكريم" فقط، ويختفي تلقائيًا في بقية الصفحات دون إيقاف الصوت
    if (typeof syncGlobalPlayerVisibility === 'function') syncGlobalPlayerVisibility();
}

// تمرير أفقي سلس لعناصر القائمة عبر عجلة الفأرة (تجربة أكثر احترافية على سطح المكتب)
document.querySelector('.nav-links')?.addEventListener('wheel', function (e) {
    if (e.deltaY === 0) return;
    e.preventDefault();
    this.scrollLeft += e.deltaY;
}, { passive: false });

const htmlRoot = document.documentElement;

// استعادة إعدادات الثيم واللون من الذاكرة المحلية عند بدء التشغيل
(function initThemeAndColor() {
    try {
        const savedTheme = localStorage.getItem('site-theme');
        const savedColor = localStorage.getItem('site-color');
        if (savedTheme) htmlRoot.setAttribute('data-theme', savedTheme);
        if (savedColor) htmlRoot.setAttribute('data-color', savedColor);
        // الاتجاه يبقى RTL دائماً مهما كانت اللغة
        htmlRoot.setAttribute('dir', 'rtl');
    } catch (e) {}
})();
document.getElementById('mode-toggle-btn').addEventListener('click', () => {
    const theme = htmlRoot.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    htmlRoot.setAttribute('data-theme', theme);
    try { localStorage.setItem('site-theme', theme); } catch (e) {}
});

function positionDropdown(btn, menu) {
    const rect = btn.getBoundingClientRect();
    const isMobile = window.innerWidth <= 768;
    const menuWidth = isMobile ? Math.min(window.innerWidth - 16, 160) : 195;
    const menuHeight = menu.scrollHeight || 250;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    // Vertical: prefer below button, flip up if not enough space
    let top = rect.bottom + 8;
    if (top + menuHeight > vh - 10) top = rect.top - menuHeight - 8;
    if (top < 8) top = 8;

    menu.style.top = top + 'px';

    if (isMobile) {
        // On mobile: always anchor to LEFT side of screen
        const leftPos = Math.max(8, rect.left);
        const clampedLeft = Math.min(leftPos, vw - menuWidth - 8);
        menu.style.left = clampedLeft + 'px';
        menu.style.right = 'auto';
        menu.style.width = menuWidth + 'px';
    } else {
        // Desktop: align to button's right edge
        let right = vw - rect.right;
        if (right + menuWidth > vw - 8) right = 8;
        menu.style.right = right + 'px';
        menu.style.left = 'auto';
        menu.style.width = '';
    }
}

document.getElementById('theme-menu-btn').addEventListener('click', (e) => {
    e.stopPropagation();
    const menu = document.getElementById('theme-menu');
    const langMenu = document.getElementById('lang-menu');
    langMenu?.classList.remove('show');
    menu.classList.toggle('show');
    if (menu.classList.contains('show')) positionDropdown(e.currentTarget, menu);
});

document.getElementById('lang-menu-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    const menu = document.getElementById('lang-menu');
    const themeMenu = document.getElementById('theme-menu');
    themeMenu.classList.remove('show');
    menu.classList.toggle('show');
    if (menu.classList.contains('show')) positionDropdown(e.currentTarget, menu);
});

window.addEventListener('click', () => {
    document.getElementById('theme-menu')?.classList.remove('show');
    document.getElementById('lang-menu')?.classList.remove('show');
});

// Close dropdowns on scroll or resize (important for mobile)
window.addEventListener('scroll', () => {
    document.getElementById('theme-menu')?.classList.remove('show');
    document.getElementById('lang-menu')?.classList.remove('show');
}, { passive: true });

window.addEventListener('resize', () => {
    document.getElementById('theme-menu')?.classList.remove('show');
    document.getElementById('lang-menu')?.classList.remove('show');
});

function changeColorTheme(color) {
    htmlRoot.setAttribute('data-color', color);
    try { localStorage.setItem('site-color', color); } catch (e) {}
    document.getElementById('theme-menu').classList.remove('show');
}

